<script setup lang="ts">
import {ref,computed,watch,onMounted,onBeforeUnmount,nextTick} from 'vue'
import axios from 'axios'
import {sha256} from '@noble/hashes/sha2.js'
import {nodeMediaUrl} from '../utils/adPlacement'
const base='/api/v1/admin/ads',headers=()=>({Authorization:'Bearer '+(localStorage.getItem('admin_token')||'cookie-session')})
const creatives=ref<any[]>([]),cid=ref(''),analyticsMode=ref(false),loading=ref(false),busy=ref(false),error=ref(''),notice=ref('')
const passport=ref<any>(null),definition=ref<any>(null),revision=ref(0),baseline=ref(''),review=ref<any>(null),checking=ref(false),options=ref<any>({genres:[]}),previewUrl=ref('')
const uploadOpen=ref(false),uploadTitle=ref(''),uploadFile=ref<File|null>(null),progress=ref(0),deleteOpen=ref(false)
const query=ref(''),kind=ref('movie'),videos=ref<any[]>([]),offset=ref(0),total=ref(0),affectedPage=ref(0),affectedQuery=ref(''),timelineLoading=ref(false)
const selected=ref<any>(null),main=ref<HTMLVideoElement|null>(null),mainUrl=ref(''),duration=ref(0),position=ref(0),adVideo=ref<HTMLVideoElement|null>(null),testAd=ref(false),testPoint=ref<any>(null),testReturn=ref(0),testBlocked=ref(false)
const analytics=ref<any>(null),days=ref(30)
let lease='',heartbeat:ReturnType<typeof setInterval>|null=null,reviewTimer:ReturnType<typeof setTimeout>|null=null,queryTimer:ReturnType<typeof setTimeout>|null=null,reviewGeneration=0,selectGeneration=0,videoGeneration=0,videoListGeneration=0,disposed=false
const selectedCreative=computed(()=>creatives.value.find(x=>x.id===cid.value))
const snapshot=()=>JSON.stringify({creative:passport.value,definition:definition.value})
const dirty=computed(()=>!!baseline.value&&snapshot()!==baseline.value)
const blocked=computed(()=>busy.value||loading.value||checking.value||!review.value||review.value.conflict_count>0||!passport.value?.title?.trim()||selectedCreative.value?.status==='deleting')
const weekdays=['Пн','Вт','Ср','Чт','Пт','Сб','Вс']
const targetKey=(x:any)=>x.kind+':'+x.id
const currentKey=computed(()=>selected.value?targetKey(selected.value):'')
const mids=computed(()=>definition.value?.slots.midpoints[currentKey.value]||[])
const marks=computed(()=>!definition.value?[]:[...(definition.value.slots.preroll?[{kind:'pre',at:0}]:[]),...Array.from(new Set([...mids.value,...(definition.value.slots.midroll_fraction&&duration.value?[Math.round(duration.value/2)]:[]),...(definition.value.slots.midroll_at_sec?[definition.value.slots.midroll_at_sec]:[]),...(definition.value.slots.interval_sec&&duration.value?Array.from({length:Math.min(100,Math.floor((duration.value-1)/definition.value.slots.interval_sec))},(_,i)=>(i+1)*definition.value.slots.interval_sec):[])])).map((at:any)=>({kind:'mid',at})),...(definition.value.slots.postroll?[{kind:'post',at:duration.value}]:[])])
const affected=computed(()=>review.value?.affected||[])
const affectedMovies=computed(()=>affected.value.filter((v:any)=>v.kind==='movie').length)
const affectedEpisodes=computed(()=>affected.value.filter((v:any)=>v.kind==='episode').length)
const affectedFiltered=computed(()=>affected.value.filter((v:any)=>v.title.toLocaleLowerCase().includes(affectedQuery.value.toLocaleLowerCase())))
const affectedVisible=computed(()=>affectedFiltered.value.slice(affectedPage.value*5,affectedPage.value*5+5))
watch(affectedQuery,()=>{affectedPage.value=0})
const unlimited=computed(()=>!!definition.value&&!definition.value.schedule.date_from&&!definition.value.schedule.date_to)
function toggleUnlimited(){if(unlimited.value){definition.value.schedule.date_from=new Date().toLocaleDateString('sv-SE',{timeZone:'Europe/Kyiv'})}else{definition.value.schedule.date_from=null;definition.value.schedule.date_to=null}}
const midMode=computed({get:()=>definition.value?.slots.midroll_fraction?'half':definition.value?.slots.midroll_at_sec?'minute':definition.value?.slots.interval_sec?'interval':'off',set:(v:string)=>{const s=definition.value.slots;s.midroll_fraction=v==='half'?0.5:null;s.midroll_at_sec=v==='minute'?600:null;s.interval_sec=v==='interval'?1500:0}})
const midEnabled=computed({get:()=>midMode.value!=='off',set:(v:boolean)=>{midMode.value=v?'half':'off'}})
const midMinute=computed({get:()=>Math.round((definition.value?.slots.midroll_at_sec||600)/60),set:(v:number)=>{definition.value.slots.midroll_at_sec=Number(v)*60}})
const intervalMinutes=computed({get:()=>Math.round((definition.value?.slots.interval_sec||0)/60),set:(v:number)=>{if(definition.value)definition.value.slots.interval_sec=Number(v)*60}})
function message(e:any){const d=e.response?.data?.detail;return typeof d==='string'?d:typeof d?.message==='string'?d.message:Array.isArray(d)?d.map((x:any)=>x.msg).join('; '):e.message||'Не удалось выполнить действие'}
async function request(path:string,method='GET',data?:any){return (await axios({url:path,method,data,headers:headers()})).data}
async function loadLibrary(){creatives.value=await request(base+'/creatives')}
async function stopPreview(){videoGeneration++;if(heartbeat)clearInterval(heartbeat);heartbeat=null;main.value?.pause();adVideo.value?.pause();mainUrl.value='';testAd.value=false;testPoint.value=null;const id=lease;lease='';if(id)try{await request('/api/v1/playback/stop','POST',{session_id:id})}catch{/* Capacity lease expires safely. */}}
async function selectCreative(id:string){if(id===cid.value&&!analyticsMode.value)return;if(dirty.value&&!window.confirm('Есть несохранённые изменения. Перейти без сохранения?'))return;const g=++selectGeneration;reviewGeneration++;loading.value=true;error.value='';notice.value='';analyticsMode.value=false;cid.value=id;baseline.value='';definition.value=null;passport.value=null;review.value=null;previewUrl.value='';selected.value=null;await stopPreview();try{const s=await request(base+'/creatives/'+id+'/settings');if(g!==selectGeneration||disposed)return;passport.value={title:s.creative.title,cta_url:s.creative.cta_url,cta_text:s.creative.cta_text,skip_after:s.creative.skip_after,status:s.creative.status==='deleting'?'paused':s.creative.status};definition.value=s.definition;revision.value=s.revision;review.value=s;affectedPage.value=0;affectedQuery.value='';baseline.value=snapshot();if(s.creative.status!=='deleting')await refreshCreativePreview()}catch(e){error.value=message(e)}finally{if(g===selectGeneration)loading.value=false}}
async function refreshCreativePreview(){const id=cid.value;try{const s=await request(base+'/creatives/'+id+'/preview');if(id===cid.value)previewUrl.value=nodeMediaUrl(s.media_url)}catch(e){error.value=message(e)}}
function tabKey(e:KeyboardEvent,index:number){const ids=[...creatives.value.map(x=>x.id),'analytics'];let n=index;if(e.key==='ArrowRight')n=(index+1)%ids.length;else if(e.key==='ArrowLeft')n=(index+ids.length-1)%ids.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=ids.length-1;else return;e.preventDefault();if(ids[n]==='analytics')void openAnalytics();else void selectCreative(ids[n]);nextTick(()=>document.querySelector<HTMLButtonElement>('[role=tab][aria-selected=true]')?.focus())}
async function checkDraft(){if(!definition.value||!cid.value||analyticsMode.value)return;const id=cid.value,g=++reviewGeneration;checking.value=true;try{const r=await request(base+'/creatives/'+id+'/settings/preview','POST',{revision:revision.value,definition:definition.value});if(g!==reviewGeneration||id!==cid.value||disposed)return;review.value=r;affectedPage.value=Math.min(affectedPage.value,Math.max(0,Math.ceil(r.affected_count/5)-1));error.value=''}catch(e){if(g===reviewGeneration){review.value=null;error.value=message(e)}}finally{if(g===reviewGeneration)checking.value=false}}
watch(definition,()=>{if(!definition.value)return;checking.value=true;reviewGeneration++;if(reviewTimer)clearTimeout(reviewTimer);reviewTimer=setTimeout(()=>void checkDraft(),300)},{deep:true,flush:'sync'})
async function save(){if(blocked.value||!definition.value)return;busy.value=true;error.value='';notice.value='';try{const r=await request(base+'/creatives/'+cid.value+'/settings','PUT',{revision:revision.value,creative:passport.value,definition:definition.value});definition.value=r.definition;revision.value=r.revision;review.value=r;baseline.value=snapshot();await loadLibrary();notice.value='Настройки ролика сохранены. Существующая чужая реклама не изменена.'}catch(e:any){if(e.response?.data?.detail?.conflicts)review.value={...review.value,conflicts:e.response.data.detail.conflicts,conflict_count:e.response.data.detail.conflict_count||1};error.value=message(e)}finally{busy.value=false}}
async function resetPlacements(){if(busy.value||!window.confirm('Отменить показ этого ролика на всех видео? Файл и статистика сохранятся. Несохранённые настройки охвата будут сброшены.'))return;busy.value=true;error.value='';try{await stopPreview();const r=await request(base+'/creatives/'+cid.value+'/reset-placements','POST',{revision:revision.value,confirm:true});definition.value=r.definition;revision.value=r.revision;review.value=r;selected.value=null;baseline.value=snapshot();notice.value='Показ ролика отменён везде. Файл, паспорт и статистика сохранены.'}catch(e){error.value=message(e)}finally{busy.value=false}}
async function removeCreative(){if(busy.value)return;busy.value=true;error.value='';try{const id=cid.value;await stopPreview();await request(base+'/creatives/'+id+'?confirm=true','DELETE');deleteOpen.value=false;cid.value='';baseline.value='';definition.value=null;passport.value=null;await loadLibrary();notice.value='Ролик, его размещения, статистика и файл Media Node удалены.';if(creatives.value.length)await selectCreative(creatives.value[0].id)}catch(e){error.value=message(e)}finally{busy.value=false}}
async function upload(){const f=uploadFile.value;if(!f)return;if(!['video/mp4','video/webm'].includes(f.type)||f.size>104857600){error.value='Выберите MP4/WebM не более 100 MiB';return}busy.value=true;error.value='';progress.value=0;try{await request('/api/v1/auth/me');const checksum=Array.from(sha256(new Uint8Array(await f.arrayBuffer()))).map(x=>x.toString(16).padStart(2,'0')).join('');const t=await request(base+'/creatives/upload-ticket','POST',{title:uploadTitle.value.trim()||f.name,size:f.size,mime:f.type,sha256:checksum,status:'active'});const url=nodeMediaUrl(t.upload_url);const r=await axios.put(url,f,{headers:{Authorization:'Bearer '+t.upload_token,'Content-Type':f.type},withCredentials:false,timeout:240000,onUploadProgress:e=>{progress.value=Math.min(99,Math.round(e.loaded/f.size*100))}});const c=await request(base+'/creatives/upload-complete','POST',{receipt:r.data.receipt});progress.value=100;uploadOpen.value=false;uploadFile.value=null;uploadTitle.value='';await loadLibrary();baseline.value='';await selectCreative(c.id);notice.value='Ролик загружен напрямую на Media Node и активен. Настройте его охват.'}catch(e){error.value=message(e)}finally{busy.value=false}}
async function loadVideos(){const g=++videoListGeneration;try{const r=await request(base+'/videos?kind='+kind.value+'&q='+encodeURIComponent(query.value)+'&offset='+offset.value+'&limit=5');if(g===videoListGeneration){videos.value=r.items;total.value=r.total}}catch(e){error.value=message(e)}}
watch([query,kind],()=>{offset.value=0;if(queryTimer)clearTimeout(queryTimer);queryTimer=setTimeout(()=>void loadVideos(),250)})
function isPicked(v:any){return definition.value?.reach.targets.some((x:any)=>targetKey(x)===targetKey(v))}
function toggleTarget(v:any){const r=definition.value.reach;if(isPicked(v))r.targets=r.targets.filter((x:any)=>targetKey(x)!==targetKey(v));else r.targets.push({kind:v.kind,id:v.id});r.excluded=r.excluded.filter((x:any)=>targetKey(x)!==targetKey(v))}
async function detach(v:any){if(dirty.value){error.value='Сначала сохраните или отмените изменения, затем открепите видео';return}busy.value=true;try{const r=await request(base+'/creatives/'+cid.value+'/targets/'+v.kind+'/'+v.id+'?revision='+revision.value,'DELETE');definition.value=r.definition;revision.value=r.revision;review.value=r;baseline.value=snapshot();notice.value='Ролик откреплён только от выбранного видео.'}catch(e){error.value=message(e)}finally{busy.value=false}}
function toggleDay(day:number){const s=definition.value.schedule;s.weekdays=s.weekdays.includes(day)?s.weekdays.filter((d:number)=>d!==day):[...s.weekdays,day].sort()}
async function chooseVideo(v:any){if(!v.available){error.value='У этого видео временно нет активного источника';return}await stopPreview();selected.value=v;duration.value=0;position.value=0;timelineLoading.value=true;await nextTick();document.getElementById('ad-timeline')?.scrollIntoView({behavior:'auto',block:'start'});const g=videoGeneration;try{const r=await request(v.kind==='movie'?'/api/v1/playback/start':'/api/v1/series_playback/start','POST',v.kind==='movie'?{movie_id:v.id}:{episode_id:v.id});if(g!==videoGeneration||disposed){if(r.session_id)await request('/api/v1/playback/stop','POST',{session_id:r.session_id});return}mainUrl.value=nodeMediaUrl(r.media_url);lease=r.session_id||'';if(lease)heartbeat=setInterval(()=>{if(lease)void request('/api/v1/playback/heartbeat','POST',{session_id:lease}).catch(()=>{})},Math.max(5,r.heartbeat_interval_seconds||15)*1000)}catch(e){error.value=message(e)}finally{if(g===videoGeneration)timelineLoading.value=false}}
function fmt(s:number){return [Math.floor(s/3600),Math.floor(s/60)%60,Math.floor(s)%60].map(x=>String(x).padStart(2,'0')).join(':')}
function metadata(){duration.value=Number.isFinite(main.value?.duration)?main.value!.duration:0}
function seek(v:number){if(main.value)main.value.currentTime=Math.max(0,Math.min(duration.value,Number(v)));position.value=Number(v)}
function addMid(at:number){if(!selected.value||!duration.value)return;const p=Math.max(1,Math.min(21600,Math.floor(duration.value-1),Math.round(at)));if(!mids.value.includes(p))definition.value.slots.midpoints[currentKey.value]=[...mids.value,p].sort((a,b)=>a-b)}
function removeMark(mark:any){if(mark.kind==='pre')definition.value.slots.preroll=false;else if(mark.kind==='post')definition.value.slots.postroll=false;else if(mids.value.includes(mark.at))definition.value.slots.midpoints[currentKey.value]=mids.value.filter((p:number)=>p!==mark.at);else midMode.value='off'}
function moveMid(old:number,next:number){const p=Math.max(1,Math.min(21600,Math.floor(duration.value-1),Math.round(next)));if(mids.value.includes(p)&&p!==old)return;definition.value.slots.midpoints[currentKey.value]=mids.value.map((x:number)=>x===old?p:x).sort((a:number,b:number)=>a-b)}
function drag(e:PointerEvent,mark:any){if(mark.kind!=='mid'||!duration.value||!mids.value.includes(mark.at))return;const el=e.currentTarget as HTMLElement,track=el.parentElement!,r=track.getBoundingClientRect();el.setPointerCapture(e.pointerId);let current=mark.at;const update=(ev:PointerEvent)=>{const p=Math.max(1,Math.min(21600,Math.floor(duration.value-1),Math.round((ev.clientX-r.left)/r.width*duration.value)));moveMid(current,p);if(mids.value.includes(p))current=p};const finish=()=>{el.removeEventListener('pointermove',update);el.removeEventListener('pointerup',finish);el.removeEventListener('pointercancel',finish)};el.addEventListener('pointermove',update);el.addEventListener('pointerup',finish);el.addEventListener('pointercancel',finish)}
async function beginTestAd(){main.value?.pause();testAd.value=true;await nextTick();try{await adVideo.value?.play()}catch{testBlocked.value=true}}
async function testTransition(mark:any){if(!mainUrl.value||!previewUrl.value)return;testBlocked.value=false;testPoint.value=mark;testReturn.value=mark.kind==='post'?duration.value:mark.at;if(mark.kind==='pre'){seek(0);await beginTestAd()}else{seek(Math.max(0,mark.at-3));try{await main.value?.play()}catch{error.value='Нажмите Play в предпросмотре, чтобы начать тест перехода'}}}
function timeupdate(){position.value=main.value?.currentTime||0;if(testPoint.value&&!testAd.value&&position.value>=Math.max(0,testReturn.value-.05))void beginTestAd()}
async function endTest(){adVideo.value?.pause();testAd.value=false;const post=testPoint.value?.kind==='post';testPoint.value=null;if(!post){seek(testReturn.value);try{await main.value?.play()}catch{}}}
async function openAnalytics(){if(dirty.value&&!window.confirm('Перейти в аналитику без сохранения изменений?'))return;analyticsMode.value=true;baseline.value='';await stopPreview();loading.value=true;try{analytics.value=await request(base+'/traffic-analytics?days='+days.value)}catch(e){error.value=message(e)}finally{loading.value=false}}
watch(days,()=>{if(analyticsMode.value)void openAnalytics()})
let modalReturn:HTMLElement|null=null
watch([uploadOpen,deleteOpen],async([u,d])=>{if(u||d){modalReturn=document.activeElement as HTMLElement;await nextTick();document.querySelector<HTMLElement>('[role="dialog"] button,[role="dialog"] input')?.focus()}else modalReturn?.focus()})
function modalKey(e:KeyboardEvent){if(!uploadOpen.value&&!deleteOpen.value)return;if(e.key==='Escape'&&!busy.value){uploadOpen.value=false;deleteOpen.value=false;e.preventDefault()}if(e.key==='Tab'){const els=[...document.querySelectorAll<HTMLElement>('[role="dialog"] button:not(:disabled),[role="dialog"] input:not(:disabled),[role="dialog"] select:not(:disabled),[role="dialog"] a[href]')];const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){last?.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first?.focus();e.preventDefault()}}}
onMounted(async()=>{document.addEventListener('keydown',modalKey);loading.value=true;try{[options.value]=await Promise.all([request(base+'/creative-options'),loadLibrary(),loadVideos()]);if(creatives.value.length)await selectCreative(creatives.value[0].id)}catch(e){error.value=message(e)}finally{loading.value=false}})
onBeforeUnmount(()=>{document.removeEventListener('keydown',modalKey);disposed=true;reviewGeneration++;selectGeneration++;if(reviewTimer)clearTimeout(reviewTimer);if(queryTimer)clearTimeout(queryTimer);void stopPreview()})
</script>
<template>
 <main class="studio">
  <header class="studio-heading"><div><p class="eyebrow">Реклама · Media Node</p><h1>Ad Studio</h1><p>Один ролик — все настройки, расписание и размещения.</p></div><button class="primary" @click="uploadOpen=true" :disabled="busy">+ Загрузить рекламный ролик</button></header>
  <div v-if="error" class="alert error" role="alert">{{error}}</div><div v-if="notice" class="alert success" role="status">{{notice}}</div>
  <nav class="creative-tabs" role="tablist" aria-label="Рекламные ролики">
   <button v-for="(c,i) in creatives" :key="c.id" role="tab" :aria-selected="!analyticsMode&&cid===c.id" :tabindex="!analyticsMode&&cid===c.id?0:-1" :id="'tab-'+c.id" aria-controls="creative-panel" @click="selectCreative(c.id)" @keydown="tabKey($event,i)"><span class="tab-title">{{c.title}}</span><span class="badge" :class="c.status">{{c.status==='active'?'Активен':c.status==='deleting'?'Удаляется — повторите':'На паузе'}}</span></button>
   <button role="tab" :aria-selected="analyticsMode" :tabindex="analyticsMode||!creatives.length?0:-1" id="analytics-tab" aria-controls="analytics-panel" @click="openAnalytics" @keydown="tabKey($event,creatives.length)">Аналитика трафика и популярных видео</button>
  </nav>
  <p v-if="loading" role="status" class="empty">Загрузка…</p>
  <section v-else-if="!analyticsMode&&passport&&definition" id="creative-panel" role="tabpanel" :aria-labelledby="'tab-'+cid">
   <form @submit.prevent="save">
    <section class="panel"><header class="section-heading"><div><p class="eyebrow">А · Паспорт рекламного ролика</p><h2>{{selectedCreative?.title}}</h2></div><div class="row"><button type="button" @click="resetPlacements" :disabled="busy">Отменить показ везде</button><button type="button" class="danger" @click="deleteOpen=true" :disabled="busy">Удалить рекламный ролик</button></div></header>
     <div class="passport-grid"><div><video v-if="previewUrl" class="creative-preview" :src="previewUrl" preload="metadata" controls playsinline aria-label="Предпросмотр рекламного ролика" @error="error='Предпросмотр недоступен. Обновите подписанный адрес.'"></video><p class="muted">Только Media Node · {{selectedCreative?.duration_sec?.toFixed(1)}} сек · {{((selectedCreative?.byte_size||0)/1048576).toFixed(1)}} MiB</p><button type="button" @click="refreshCreativePreview">Обновить адрес предпросмотра</button></div>
      <div class="fields"><label>Название<input v-model="passport.title" required maxlength="160" /></label><label>Ссылка рекламодателя (CTA URL)<input v-model="passport.cta_url" type="url" maxlength="2048" placeholder="https://…" /></label><label>Текст кнопки перехода<input v-model="passport.cta_text" maxlength="80" placeholder="Подробнее" /></label><div class="row"><label>Пропуск<select v-model="passport.skip_after"><option :value="null">Без пропуска</option><option :value="5">Пропуск через 5 сек</option><option :value="10">Пропуск через 10 сек</option></select></label><label>Статус<select v-model="passport.status"><option value="active">Активен</option><option value="paused">На паузе</option></select></label></div><p class="muted">Пауза не освобождает занятые позиции для других роликов.</p></div>
     </div>
     <dl class="stats"><div><dt>Показы</dt><dd>{{selectedCreative?.impressions||0}}</dd></div><div><dt>Досмотры до конца</dt><dd>{{selectedCreative?.completions||0}}</dd></div><div><dt>Переходы по ссылке</dt><dd>{{selectedCreative?.clicks||0}}</dd></div></dl>
    </section>
    <section class="panel"><p class="eyebrow">Б · Дни и время</p><h2>Расписание показа этого ролика</h2><p class="muted">Часовой пояс Europe/Kyiv. Конец периода и последняя минута включены.</p><div class="row"><label>С даты<input type="date" :value="definition.schedule.date_from||''" @input="definition.schedule.date_from=($event.target as HTMLInputElement).value||null" /></label><label>По дату<input type="date" :value="definition.schedule.date_to||''" @input="definition.schedule.date_to=($event.target as HTMLInputElement).value||null" /></label><button type="button" class="schedule-toggle" :aria-pressed="unlimited" @click="toggleUnlimited">{{unlimited?"✓ Бессрочно":"Заданы даты — включить бессрочно"}}</button></div>
     <div class="weekdays" role="group" aria-label="Дни недели"><button type="button" v-for="(day,i) in weekdays" :key="day" :aria-pressed="definition.schedule.weekdays.includes(i)" @click="toggleDay(i)">{{day}}</button></div>
     <label class="check"><input type="checkbox" v-model="definition.schedule.all_day" />{{definition.schedule.all_day?"✓ Круглосуточно 24/7":"Круглосуточно 24/7"}}</label><div class="row" v-if="!definition.schedule.all_day"><label>С времени<input type="time" v-model="definition.schedule.time_from" required /></label><label>По время<input type="time" v-model="definition.schedule.time_to" required /></label></div>
    </section>
    <section class="panel"><p class="eyebrow">В · Охват и сегменты</p><h2>Где показывать этот ролик</h2><fieldset class="reach"><legend class="sr-only">Выбор охвата</legend><label class="check"><input type="radio" v-model="definition.reach.mode" value="all" />Все фильмы и сериалы портала</label><label class="check"><input type="radio" v-model="definition.reach.mode" value="genres" />Определённые жанры / сегменты</label><label class="check"><input type="radio" v-model="definition.reach.mode" value="popular" />Топ популярных видео</label><label class="check"><input type="radio" v-model="definition.reach.mode" value="selected" />Выборочно конкретные фильмы и серии</label></fieldset>
     <div v-if="definition.reach.mode==='genres'" class="genre-list"><label class="check" v-for="g in options.genres" :key="g.id"><input type="checkbox" :value="g.id" v-model="definition.reach.genre_ids" />{{g.name}}</label></div>
     <div v-if="definition.reach.mode==='popular'"><label>Количество популярных видео<input type="number" min="1" max="100" v-model.number="definition.reach.top_n" /></label><p class="muted">Автовыбор по запускам за 30 дней. Состав обновляется при сохранении, не меняется скрытно после него.</p></div>
     <div v-if="definition.reach.mode==='selected'"><div class="row"><label>Поиск видео<input type="search" v-model="query" placeholder="Название фильма или серии" /></label><label>Тип<select v-model="kind"><option value="movie">Фильмы</option><option value="episode">Серии</option></select></label></div><div class="video-options"><label v-for="v in videos" :key="targetKey(v)" class="check"><input type="checkbox" :checked="isPicked(v)" @change="toggleTarget(v)" />{{v.title}}</label><p v-if="!videos.length" class="muted">Ничего не найдено</p></div><div class="row pagination"><button type="button" :disabled="offset===0" @click="offset-=5;loadVideos()">Назад</button><span>{{total?offset+1:0}}–{{Math.min(offset+5,total)}} из {{total}}</span><button type="button" :disabled="offset+5>=total" @click="offset+=5;loadVideos()">Далее</button></div></div>
     <label class="affected-search">Поиск в затронутых видео<input type="search" v-model="affectedQuery" placeholder="Найти фильм или серию" /></label><h3>Какие фильмы затрагивает сейчас <span class="badge">{{review?.affected_count||0}}</span></h3><p class="muted">Доступно в выбранном охвате: {{affectedMovies}} фильмов · {{affectedEpisodes}} серий. Недоступные записи исключены.</p><p v-if="checking" role="status">Проверка охвата и пересечений…</p><p class="muted">{{dirty?'Предпросмотр несохранённого охвата.':'Сохранённые привязки.'}} {{review?.schedule_active_now?'Сейчас время показа.':'Сейчас вне расписания.'}}</p>
     <ul class="affected-list"><li v-for="v in affectedVisible" :key="targetKey(v)"><span>{{v.title}}</span><div class="row"><button type="button" @click="chooseVideo(v)" :disabled="!v.available">Открыть таймлайн</button><button type="button" class="danger-text" @click="detach(v)" :disabled="dirty||busy">✕ Открепить</button></div></li></ul><p v-if="!affected.length" class="muted">Нет доступных видео в выбранном охвате.</p><div class="row pagination" v-if="affectedFiltered.length>5"><button type="button" :disabled="affectedPage===0" @click="affectedPage--">Назад</button><span>Страница {{affectedPage+1}} из {{Math.ceil(affectedFiltered.length/5)}}</span><button type="button" :disabled="(affectedPage+1)*5>=affectedFiltered.length" @click="affectedPage++">Далее</button></div>
     <div v-if="definition.reach.excluded.length" class="muted">Исключено вручную: {{definition.reach.excluded.length}} <button type="button" @click="definition.reach.excluded=[]">Вернуть в охват (с проверкой конфликтов)</button></div>
    </section>
    <section class="panel"><p class="eyebrow">Г · Где вставляется</p><h2>Позиции этого рекламного ролика</h2><p class="muted">Общие Pre-roll, Post-roll и интервал применяются к охвату ролика. Точные маркеры — к выбранному видео.</p><div class="row"><label class="check"><input type="checkbox" v-model="definition.slots.preroll" />В начале видео (Pre-roll · 00:00:00)</label><label class="check"><input type="checkbox" v-model="definition.slots.postroll" />В конце видео (Post-roll)</label></div><label class="check"><input type="checkbox" v-model="midEnabled" />В середине видео (Mid-roll)</label><div class="midroll-settings" v-if="midEnabled"><label>Режим Mid-roll<select v-model="midMode"><option value="half">Ровно посередине видео (50% длительности)</option><option value="minute">На конкретной минуте от начала видео</option><option value="interval">Повторять через каждые N минут просмотра</option></select></label><label v-if="midMode==='minute'">Минута от начала<input type="number" min="1" max="120" step="1" v-model.number="midMinute" /></label><label v-if="midMode==='interval'">Повторять каждые N минут<input type="number" min="1" max="120" step="1" v-model.number="intervalMinutes" /></label></div>
     <p v-if="!selected" class="empty">Выберите «Открыть таймлайн» у видео в списке охвата выше.</p>
     <div v-else id="ad-timeline" class="timeline-editor"><p v-if="timelineLoading" role="status">Открываем поток Media Node…</p><h3>{{selected.title}}</h3><div class="preview-stage"><video v-if="mainUrl" ref="main" :src="mainUrl" controls playsinline preload="auto" @loadedmetadata="metadata" @durationchange="metadata" @timeupdate="timeupdate" @ended="testPoint?.kind==='post'&&beginTestAd()" @error="error='Не удалось загрузить поток Media Node. Повторно откройте таймлайн.'"></video><div v-if="testAd" class="test-overlay"><video ref="adVideo" :src="previewUrl" preload="auto" playsinline @ended="endTest" @error="error='Ролик предпросмотра недоступен';endTest()"></video><span>Тест рекламы · не учитывается в показах</span><button v-if="testBlocked" type="button" @click="adVideo?.play();testBlocked=false">Продолжить тест</button></div></div><p class="muted">Media Node · {{fmt(position)}} / {{fmt(duration)}} · реальная длительность потока</p>
      <input class="scrubber" type="range" min="0" :max="duration||1" step="1" :value="position" :disabled="!duration" aria-label="Позиция в фильме" @input="seek(Number(($event.target as HTMLInputElement).value))" />
      <div class="timeline-track" aria-label="Рекламные маркеры"><button type="button" v-for="m in marks" :key="m.kind+'-'+m.at" class="marker" :style="{left:Math.min(98,Math.max(2,m.at/(duration||1)*100))+'%'}" :aria-label="(m.kind==='pre'?'Pre-roll':m.kind==='post'?'Post-roll':'Mid-roll')+' '+fmt(m.at)" @pointerdown="drag($event,m)" @keydown.left.prevent="m.kind==='mid'&&moveMid(m.at,m.at-1)" @keydown.right.prevent="m.kind==='mid'&&moveMid(m.at,m.at+1)" @click="seek(m.at)">◆</button></div>
      <div class="row"><button type="button" @click="definition.slots.preroll=true">+ В начало (Pre-roll)</button><button type="button" :disabled="!duration" @click="addMid(position)">+ Вставить рекламу в {{fmt(position)}}</button><button type="button" :disabled="!duration" @click="addMid(duration/2)">+ В середину (50%)</button><button type="button" @click="definition.slots.postroll=true">+ В конец (Post-roll)</button></div><ul class="marker-list"><li v-for="m in marks" :key="m.kind+'-'+m.at"><span>{{m.kind==='pre'?'Pre-roll':m.kind==='post'?'Post-roll':'Mid-roll'}} · {{fmt(m.at)}}</span><div class="row"><button type="button" :disabled="!duration||!previewUrl" @click="testTransition(m)">▶ Тест перехода</button><button type="button" @click="removeMark(m)">Убрать маркер</button></div></li></ul>
     </div>
    </section>
    <section v-if="review?.conflict_count" class="conflicts" role="alert"><h2>Существующая реклама защищена</h2><p v-for="(c,i) in review.conflicts" :key="i">{{c.message}}</p><p v-if="review.conflict_count>review.conflicts.length">Всего пересечений: {{review.conflict_count}}. Показаны первые {{review.conflicts.length}}.</p><p>Сначала явно открепите старую рекламу во вкладке её ролика либо измените охват, расписание или позиции.</p></section>
    <footer class="save-bar"><span>{{checking?'Проверяем пересечения…':dirty?'Есть несохранённые изменения':'Все изменения сохранены'}}</span><button class="primary" type="submit" :disabled="blocked||!dirty">Сохранить настройки ролика</button><button type="button" :disabled="busy||!dirty" @click="baseline='';const id=cid;cid='';selectCreative(id)">Отменить изменения</button></footer>
   </form>
  </section>
  <section v-else-if="analyticsMode" id="analytics-panel" role="tabpanel" aria-labelledby="analytics-tab" class="panel"><div class="section-heading"><div><p class="eyebrow">Наблюдаемые данные, не оценки</p><h2>Аналитика трафика и популярных видео</h2></div><label>Период<select v-model.number="days"><option :value="7">7 дней</option><option :value="30">30 дней</option><option :value="90">90 дней</option></select></label></div>
   <template v-if="analytics"><p>Просмотров с телеметрией: <b>{{analytics.measured_sessions}}</b> · уникальных зрителей: <b>{{analytics.unique_viewers}}</b></p><p v-if="!analytics.measured_sessions" class="empty">Новая телеметрия пока не накоплена. Исторические запуски показаны отдельно, без выдуманного удержания.</p><div class="table-scroll"><table><caption>Топ видео: исторические запуски и измеренные просмотры</caption><thead><tr><th>Видео</th><th>Запуски авторизации</th><th>Просмотры</th><th>Уникальные зрители</th><th>Удержание / выборка</th><th>Установленная реклама</th></tr></thead><tbody><tr v-for="v in analytics.top" :key="v.kind+v.id"><td>{{v.title}}</td><td>{{v.authorized_starts}}</td><td>{{v.views}}</td><td>{{v.unique_viewers}}</td><td>{{v.retention_pct==null?'Нет данных':v.retention_pct+'%'}} / {{v.retention_sample}}</td><td>{{v.ads.join(', ')||'Нет'}}</td></tr></tbody></table></div>
    <div class="analytics-grid"><div><h3>Начало просмотров по часам · Europe/Kyiv</h3><table><thead><tr><th>Час</th><th>Просмотры</th></tr></thead><tbody><tr v-for="h in analytics.hours" :key="h.hour"><td>{{String(h.hour).padStart(2,'0')}}:00</td><td>{{h.views}}</td></tr></tbody></table></div><div><h3>По дням недели</h3><table><tbody><tr v-for="w in analytics.weekdays" :key="w.weekday"><th>{{weekdays[w.weekday]}}</th><td>{{w.views}}</td></tr></tbody></table><h3>Устройства</h3><p v-if="!analytics.devices.length" class="muted">Нет наблюдений</p><table><tbody><tr v-for="d in analytics.devices" :key="d.name"><th>{{d.name}}</th><td>{{d.views}}</td></tr></tbody></table><h3>География</h3><p class="muted">Нет доверенного источника географии. Страны не определяются по догадке.</p><h3>Источники переходов</h3><p v-if="!analytics.referrers.length" class="muted">Нет наблюдений</p><table><tbody><tr v-for="r in analytics.referrers" :key="r.name"><th>{{r.name}}</th><td>{{r.views}}</td></tr></tbody></table></div></div><details><summary>Как считаются показатели и что пока недоступно</summary><ul><li v-for="n in analytics.notes" :key="n">{{n}}</li></ul></details>
   </template>
  </section>
  <section v-else-if="!loading" class="panel empty"><h2>Загрузите первый рекламный ролик</h2><p>Его предпросмотр, расписание, охват и тайминги появятся в одной вкладке.</p></section>
  <div v-if="uploadOpen" class="modal-backdrop" @click.self="!busy&&(uploadOpen=false)"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="upload-title"><h2 id="upload-title">Загрузить рекламный ролик</h2><form @submit.prevent="upload"><label>Название<input v-model="uploadTitle" maxlength="160" /></label><label>Видео MP4 / WebM · до 100 MiB<input type="file" accept="video/mp4,video/webm" required @change="uploadFile=($event.target as HTMLInputElement).files?.[0]||null" /></label><p class="muted">Файл загружается напрямую на Media Node. Новый ролик сразу активен; охват настраивается отдельно.</p><p v-if="busy" role="status">{{progress}}% · загрузка / обработка на Media Node</p><div class="row"><button class="primary" :disabled="busy||!uploadFile">Загрузить</button><button type="button" :disabled="busy" @click="uploadOpen=false">Отмена</button></div></form></section></div>
  <div v-if="deleteOpen" class="modal-backdrop" @click.self="!busy&&(deleteOpen=false)"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="delete-title"><h2 id="delete-title">Удалить «{{selectedCreative?.title}}»?</h2><p>Будут удалены этот ролик, все его привязки, его рекламная статистика и физический файл на Media Node. Другие ролики не изменятся.</p><p>Это действие необратимо.</p><p v-if="error" role="alert" class="error">{{error}}</p><div class="row"><button class="danger" :disabled="busy" @click="removeCreative">{{busy?'Удаление…':'Да, удалить ролик и файл'}}</button><button :disabled="busy" @click="deleteOpen=false">Отмена</button></div></section></div>
